const c = $json;
const orders = Number(c.orders_count || 0);
const spent = Number(c.total_spent || 0);
let segment = 'NEW';
if (orders >= 1 && spent >= 500) segment = 'HIGH_VALUE';
else if (orders > 1) segment = 'RETURNING';
return [{ json: {
  event_type: 'CUSTOMER',
  execution_id: $execution.id,
  timestamp: new Date().toISOString(),
  shopify_customer_id: String(c.id || ''),
  customer_name: [c.first_name, c.last_name].filter(Boolean).join(' ').trim(),
  customer_email: c.email || '',
  customer_phone: c.phone || '',
  total_orders: orders,
  total_spent: spent,
  avg_order_value: orders > 0 ? Number((spent / orders).toFixed(2)) : 0,
  customer_segment: segment,
  last_order: String(c.last_order_id || ''),
  created_at: c.created_at || '',
} }];

const r = $json;
const txns = Array.isArray(r.transactions) ? r.transactions : [];
const refundAmount = txns.reduce((s, t) => s + (Number(t.amount) || 0), 0);
return [{ json: {
  event_type: 'FINANCIAL',
  execution_id: $execution.id,
  timestamp: new Date().toISOString(),
  refund_id: String(r.id || ''),
  shopify_order_id: String(r.order_id || ''),
  refund_amount: refundAmount,
  created_at: r.created_at || '',
} }];

const items = [];
const src = $json;
const lineItems = Array.isArray(src.line_items) ? src.line_items : [];
for (const li of lineItems) {
  items.push({ json: {
    sku: li.sku || '', shopify_product_id: String(li.product_id || ''),
    product_name: li.title || '', sold_quantity: Number(li.quantity || 0),
    last_checked: src.timestamp,
  } });
}
return items;

