parameters.jsCode:
const base = $('MASTER - Normalize Product').item.json;
let ai = {};
try {
  const raw = $json.output || $json.text || '{}';
  ai = typeof raw === 'string' ? JSON.parse(raw.replace(/^\`\`\`json|\`\`\`$/g, '').trim()) : raw;
} catch (e) { ai = {}; }

const cost = 0; // supplier cost unknown from webhook; enriched later from Products sheet
const sellingPrice = Number(base.selling_price || 0);
const recommended = Number(ai.recommended_price || sellingPrice);
const profit = Number((sellingPrice - cost).toFixed(2));
const margin = sellingPrice > 0 ? Number(((profit / sellingPrice) * 100).toFixed(2)) : 0;

// Business rules: never publish unless AI approves AND no human approval required.
const aiApproved = (ai.decision === 'APPROVE') && (ai.requires_human_approval === false);
const approvalStatus = aiApproved ? 'APPROVED' : 'PENDING';

return [{ json: {
  ...base,
  ai_title: ai.title || base.product_name,
  ai_description: ai.description || '',
  short_description: ai.short_description || '',
  benefits: Array.isArray(ai.benefits) ? ai.benefits.join('; ') : '',
  ai_tags: Array.isArray(ai.tags) ? ai.tags.join(', ') : base.tags,
  ai_category: ai.category || base.category,
  seo_title: ai.seo_title || '',
  meta_description: ai.meta_description || '',
  keywords: Array.isArray(ai.keywords) ? ai.keywords.join(', ') : '',
  recommended_price: recommended,
  profit,
  profit_margin: margin,
  ai_score: Number(ai.ai_score || 0),
  ai_confidence: Number(ai.confidence || 0),
  ai_decision: ai.decision || 'REVIEW',
  requires_human_approval: ai.requires_human_approval !== false,
  ai_reason: ai.reason || '',
  approval_status: approvalStatus,
  seo_status: 'PENDING',
} }];

const REORDER = 5;
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const variants = Array.isArray(p.variants) ? p.variants : [];
  for (const v of variants) {
    const stock = Number(v.inventory_quantity || 0);
    let status = 'IN STOCK';
    if (stock === 0) status = 'OUT OF STOCK';
    else if (stock <= REORDER) status = 'LOW STOCK';
    out.push({ json: {
      sku: v.sku || '',
      shopify_product_id: String(p.id || ''),
      product_name: p.title || '',
      current_stock: stock,
      reorder_level: REORDER,
      stock_status: status,
      needs_attention: status !== 'IN STOCK',
      last_checked: new Date().toISOString(),
    } });
  }
}
return out;

