const rows = $input.all().map(i => i.json).filter(r => Object.keys(r).length > 0);
let revenue = 0;
const productCount = {};
for (const r of rows) {
  revenue += Number(r['Order Value'] || 0);
  const prods = String(r['Products'] || '').split(',').map(s => s.trim()).filter(Boolean);
  for (const p of prods) productCount[p] = (productCount[p] || 0) + 1;
}
const orders = rows.length;
const aov = orders > 0 ? Number((revenue / orders).toFixed(2)) : 0;
const ranked = Object.keys(productCount).map(k => ({ name: k, count: productCount[k] })).sort((a,b) => b.count - a.count);
const best = ranked.slice(0, 5).map(x => x.name + ' (' + x.count + ')').join(', ');
const worst = ranked.slice(-3).map(x => x.name + ' (' + x.count + ')').join(', ');
return [{ json: {
  report_date: new Date().toISOString().slice(0,10),
  total_orders: orders,
  total_revenue: Number(revenue.toFixed(2)),
  avg_order_value: aov,
  best_sellers: best || 'none',
  worst_performers: worst || 'none',
} }];

