const MIN_PROFIT_MARGIN = 0.30; // 30%
const MAX_PRICE_CHANGE = 0.15;   // 15%
const SHIPPING = 3.00;
const out = [];
for (const item of $input.all()) {
  const r = item.json;
  if (!r || Object.keys(r).length === 0) continue;
  const cost = Number(r['Cost Price'] || 0);
  const current = Number(r['Selling Price'] || 0);
  if (current <= 0) continue;
  // Recommended = (cost + shipping) / (1 - margin)
  const recommended = Number(((cost + SHIPPING) / (1 - MIN_PROFIT_MARGIN)).toFixed(2));
  const changePct = current > 0 ? Math.abs(recommended - current) / current : 1;
  const smallChange = changePct <= MAX_PRICE_CHANGE;
  out.push({ json: {
    execution_id: $execution.id,
    timestamp: new Date().toISOString(),
    shopify_product_id: String(r['Shopify Product ID'] || ''),
    product_name: r['Product Name'] || '',
    cost, current_price: current,
    recommended_price: recommended,
    change_pct: Number((changePct * 100).toFixed(2)),
    within_threshold: smallChange,
    approval_status: smallChange ? 'AUTO_APPROVED' : 'PENDING',
  } });
}
return out;

